CREATE COLUMN TABLE "TEST_AP"."OCLO" ("Code" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(50) NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "Locked" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("Code")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OCLO_NAME" ON "TEST_AP"."OCLO" ( "Name" ASC )